<template><div><div class="page-head"><div><span>PHM INTEGRATION / KNOWLEDGE</span><h2>FMECA 故障知识库</h2><p>统一管理故障模式、原因与危害等级，支持筛选和详情查看。</p></div><el-button :loading="loading" @click="load">刷新数据</el-button></div><div class="stats"><el-card><small>记录总数</small><strong>{{rows.length}}</strong></el-card><el-card><small>高危记录</small><strong class="danger">{{highRisk}}</strong></el-card><el-card><small>涉及部件</small><strong>{{components}}</strong></el-card></div><el-card shadow="never"><div class="filters"><el-input v-model="keyword" clearable placeholder="搜索部件、故障模式或原因" style="width:280px"/><el-select v-model="severity" clearable placeholder="危害等级" style="width:150px"><el-option v-for="x in severities" :key="x" :label="x" :value="x"/></el-select><el-select v-model="component" clearable placeholder="部件" style="width:180px"><el-option v-for="x in componentOptions" :key="x" :label="x" :value="x"/></el-select><el-button @click="reset">清空筛选</el-button></div><el-table :data="filtered" stripe v-loading="loading" @row-click="show"><el-table-column prop="id" label="序号" width="70"/><el-table-column prop="component" label="部件" width="150"/><el-table-column prop="fault_name" label="故障模式" width="180"/><el-table-column prop="fault_prob" label="故障概率" width="110"/><el-table-column prop="fault_reason" label="可能原因" min-width="240"/><el-table-column label="危害等级" width="120"><template #default="s"><el-tag :type="isHigh(s.row.degree_harm)?'danger':'warning'">{{s.row.degree_harm||'未分级'}}</el-tag></template></el-table-column><el-table-column label="操作" width="90"><template #default="s"><el-button link type="primary" @click.stop="show(s.row)">详情</el-button></template></el-table-column></el-table><el-empty v-if="!loading&&!filtered.length" description="没有匹配的故障记录"/></el-card><el-drawer v-model="drawer" title="故障模式详情" size="500px"><el-descriptions v-if="current" :column="1" border><el-descriptions-item v-for="(v,k) in detailItems" :key="k" :label="k">{{v||'—'}}</el-descriptions-item></el-descriptions></el-drawer></div></template>
<script setup>import{ref,computed,onMounted}from'vue';import{ElMessage}from'element-plus';const rows=ref([]),loading=ref(false),keyword=ref(''),severity=ref(''),component=ref(''),drawer=ref(false),current=ref(null),severities=['Ⅰ','Ⅱ','Ⅲ','Ⅳ'];const load=async()=>{loading.value=true;try{const r=await fetch('/api/v1/integrations/wujiaxin/fmeca/');if(!r.ok)throw Error();rows.value=(await r.json()).results||[]}catch{ElMessage.error('FMECA 数据加载失败')}finally{loading.value=false}};onMounted(load);const componentOptions=computed(()=>[...new Set(rows.value.map(x=>x.component).filter(Boolean))]);const filtered=computed(()=>{const k=keyword.value.trim().toLowerCase();return rows.value.filter(x=>(!k||Object.values(x).join(' ').toLowerCase().includes(k))&&(!severity.value||x.degree_harm===severity.value)&&(!component.value||x.component===component.value))});const highRisk=computed(()=>rows.value.filter(x=>String(x.degree_harm||'').includes('Ⅰ')).length),components=computed(()=>componentOptions.value.length);const isHigh=v=>String(v||'').includes('Ⅰ');const reset=()=>{keyword.value='';severity.value='';component.value=''};const show=row=>{current.value=row;drawer.value=true};const detailItems=computed(()=>current.value?{'部件':current.value.component,'故障模式':current.value.fault_name,'故障概率':current.value.fault_prob,'可能原因':current.value.fault_reason,'影响':current.value.fault_effect,'危害等级':current.value.degree_harm,'检测方法':current.value.detection_method}:{});</script>
<style scoped>.page-head{display:flex;justify-content:space-between;align-items:end;margin-bottom:18px}.page-head span{font-size:11px;color:#2c82e7;font-weight:700;letter-spacing:1px}.page-head h2{margin:7px 0}.page-head p{margin:0;color:#8391a5}.stats{display:flex;gap:14px;margin-bottom:16px}.stats .el-card{flex:1}.stats small{color:#8997a9}.stats strong{display:block;font-size:25px;margin-top:6px}.danger{color:#e45656}.filters{display:flex;gap:10px;margin-bottom:15px;flex-wrap:wrap}.el-card{border-radius:11px}</style>
